import base64
import json

# Get the response from Nano Banana
input_data = _input.all()
response_body = input_data[0].json

# Extract the base64 image from response
# Response format: {"choices": [{"message": {"images": [{"image_url": {"url": "data:image/png;base64,..."}}]}}]}
try:
    cleaned_image_url = response_body['choices'][0]['message']['images'][0]['image_url']['url']

    # Extract just the base64 part
    if cleaned_image_url.startswith('data:image'):
        cleaned_image_base64 = cleaned_image_url.split(',')[1]
    else:
        cleaned_image_base64 = cleaned_image_url

    return [
        {
            "json": {
                "cleaned_image": cleaned_image_url,
                "cleaned_image_base64": cleaned_image_base64,
                "status": "success"
            }
        }
    ]
except (KeyError, IndexError) as e:
    return [
        {
            "json": {
                "error": f"Failed to extract image from Nano Banana response: {str(e)}",
                "raw_response": response_body,
                "status": "error"
            }
        }
    ]

import base64

# Get the final check image base64
input_data = _input.first()
final_image_b64 = input_data.json.get('final_check_image_base64')

# Decode base64 to binary
image_binary = base64.b64decode(final_image_b64)

# Return as binary data for Write Binary File node
return [
    {
        "binary": {
            "data": {
                "data": image_binary,
                "mimeType": "image/png",
                "fileName": "check-output.png"
            }
        },
        "json": input_data.json
    }
]
